package org.catrobat.catroid.content.bricks;

import org.catrobat.catroid.R;
import org.catrobat.catroid.content.Sprite;
import org.catrobat.catroid.content.actions.ScriptSequenceAction;
import org.catrobat.catroid.formulaeditor.Formula;
import org.catrobat.catroid.formulaeditor.UserVariable;

/**
 * Creates the directory skeleton of a Wine prefix inside the app's private
 * storage and reports what it did.
 *
 * It does not claim to produce a working Windows prefix: the registry hives and
 * the contents of C:\ are generated by Wine's own {@code wineboot}, which is
 * why the block's report always ends by naming that remaining step.
 */
public class PcPreparePrefixBrick extends UserVariableBrickWithFormula {
    private static final long serialVersionUID = 1L;

    public PcPreparePrefixBrick() {
        addAllowedBrickField(BrickField.TEXT, R.id.brick_pc_prefix_name_edit);
    }

    public PcPreparePrefixBrick(String prefixName) {
        this(new Formula(prefixName));
    }

    public PcPreparePrefixBrick(Formula prefixName) {
        this();
        setFormulaWithBrickField(BrickField.TEXT, prefixName);
    }

    @Override
    public int getViewResource() {
        return R.layout.brick_pc_prepare_prefix;
    }

    @Override
    protected int getSpinnerId() {
        return R.id.brick_pc_prefix_variable_spinner;
    }

    @Override
    public void addActionToSequence(Sprite sprite, ScriptSequenceAction sequence) {
        sequence.addAction(sprite.getActionFactory()
                .createPcPreparePrefixAction(sprite, sequence,
                        getFormulaWithBrickField(BrickField.TEXT), userVariable));
    }
}
